head.script:
// 기존 JavaScript 코드 유지

scwin.onpageload = function () {
    if (!window.userList) {
        window.userList = window.mf_contentFrame_userList;
        console.log("userList 컴포넌트 설정 완료");
    }

    scwin.btn_search_onclick();
    scwin.createPopupLayer();
};

scwin.mergeUploadedData = function() {
    console.log("=== 업로드된 데이터 병합 시작 ===");

    try {
        // 현재 업로드된 데이터 가져오기
        var uploadedData = userList.getAllJSON();
        console.log("업로드된 데이터:", uploadedData);
        console.log("백업된 원본 데이터:", scwin.originalDataBackup);

        // 업로드된 데이터가 기존 데이터와 같은지 확인
        if (scwin.originalDataBackup && scwin.originalDataBackup.length > 0 && 
            uploadedData && uploadedData.length > 0) {

            var isSameData = true;
            if (uploadedData.length === scwin.originalDataBackup.length) {
                for (var i = 0; i < uploadedData.length; i++) {
                    if (uploadedData[i].name !== scwin.originalDataBackup[i].name ||
                        uploadedData[i].email !== scwin.originalDataBackup[i].email) {
                        isSameData = false;
                        break;
                    }
                }
            } else {
                isSameData = false;
            }

            if (isSameData) {
                console.log("업로드된 데이터가 기존 데이터와 동일합니다. 실제 Excel 파일을 업로드해주세요.");
                scwin.showPopup("Excel 파일이 제대로 업로드되지 않았습니다.\\n다른 Excel 파일을 선택하여 다시 업로드해주세요.");

                // 기존 데이터로 복원
                userList.setJSON(scwin.originalDataBackup);
                return;
            }
        }

        // **수정된 부분: 기존 데이터 + 새 데이터 분리 처리**
        var finalData = [];
        const tenantId = $p.getParameter("tenant");

        // 1. 기존 데이터 먼저 추가
        if (scwin.originalDataBackup && scwin.originalDataBackup.length > 0) {
            scwin.originalDataBackup.forEach(function(item) {
                finalData.push(item);
            });
            console.log("기존 데이터 추가 완료:", scwin.originalDataBackup.length, "개");
        }

        // 2. 새로운 업로드 데이터만 처리 (기존 데이터 제외)
        if (uploadedData && uploadedData.length > scwin.originalDataCount) {
            var newDataOnly = uploadedData.slice(scwin.originalDataCount);

            newDataOnly.forEach(function(item, index) {
                // 새 데이터 기본 설정
                item.tenantId = tenantId;
                item.passwordChanged = "Y";
                item.originalPassword = item.password || "0000";
                item.password = item.password || "0000";

                finalData.push(item);
                console.log(`새로운 Excel 데이터 ${index + 1} 처리 완료:`, {
                    tenantId: item.tenantId,
                    name: item.name,
                    email: item.email,
                    role: item.role,
                    password: item.password
                });
            });
            console.log("새로운 Excel 데이터 추가 완료:", newDataOnly.length, "개");
        }

        // 3. **중요: 한 번만 데이터 설정하고 insertRow는 사용하지 않음**
        userList.setJSON(finalData);

        console.log("데이터 병합 완료. 총 행 수:", userList.getTotalRow());
        console.log("기존:", scwin.originalDataCount, "새로 추가:", finalData.length - scwin.originalDataCount);

        // 4. 역할 매핑 처리 (새로 추가된 데이터만)
        scwin.fixRoleMappingForNewData(scwin.originalDataCount);

        // 5. 중복 검사 시작
        setTimeout(function () {
            console.log("새로 추가된 Excel 데이터 중복 검사 시작...");
            scwin.checkUploadedEmailDuplicates(scwin.originalDataCount);
        }, 500);

    } catch (err) {
        console.error("데이터 병합 중 오류:", err);
        scwin.showPopup("데이터 병합 중 오류가 발생했습니다: " + err.message);
    }
};



// 팝업 레이어 생성 함수
scwin.createPopupLayer = function () {
    if (document.getElementById('customAlertPopup')) return;

    var popupHtml = `
            <div id="customAlertPopup" style="position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 9999; display: none; align-items: center; justify-content: center; font-family: 'Pretendard', sans-serif;">
                <div style="background: white; padding: 24px; border-radius: 8px; box-shadow: 0 5px 15px rgba(0,0,0,0.3); min-width: 320px; max-width: 450px; text-align: center; box-sizing: border-box;">
                    <div id="popupMessage" style="margin-bottom: 24px; font-size: 16px; line-height: 1.6; color: #333; white-space: pre-wrap; word-break: break-word;"></div>
                    <div>
                        <button id="popupConfirm" style="background: #3674B5; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">확인</button>
                        <button id="popupCancel" style="background: #6c757d; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">취소</button>
                    </div>
                </div>
            </div>
        `;
    document.body.insertAdjacentHTML('beforeend', popupHtml);
};

// 팝업 표시 함수
scwin.showPopup = function (message, isConfirm, callback) {
    var popup = document.getElementById('customAlertPopup');
    if (!popup) {
        scwin.createPopupLayer();
        popup = document.getElementById('customAlertPopup');
    }

    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    messageEl.innerHTML = message.replace(/\\n/g, '<br>');

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(true);
        };
        cancelBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(false);
        };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback();
        };
    }

    popup.style.display = 'flex';
};

scwin.btn_insert_onclick = function (e) {
    const tenantId = $p.getParameter("tenant");
    if (!tenantId || tenantId.trim() === "") {
        scwin.showPopup("테넌트 정보가 없어 사용자를 추가할 수 없습니다.");
        return;
    }

    var _rowIdx = userList.insertRow();
    userList.setCellData(_rowIdx, "tenantId", tenantId);
    userList.setCellData(_rowIdx, "passwordChanged", "Y");
    userList.setCellData(_rowIdx, "password", "0000"); // 기본 비밀번호 0000
    userList.setCellData(_rowIdx, "originalPassword", "0000");

    console.log(`새 행 추가 완료 - 행: ${_rowIdx}, tenantId: ${tenantId}, 기본 비밀번호: 0000`);
};

scwin.btn_delete_onclick = function (e) {
    if (grd.getFocusedRowIndex() < 0) {
        scwin.showPopup("삭제할 행을 먼저 선택해주세요.");
        return;
    }
    userList.deleteRow(grd.getFocusedRowIndex());
};


scwin.btn_delete_onclick = function (e) {
    if (grd.getFocusedRowIndex() < 0) {
        scwin.showPopup("삭제할 행을 먼저 선택해주세요.");
        return;
    }
    userList.deleteRow(grd.getFocusedRowIndex());
};

scwin.btn_deleteRows_onclick = function (e) {
    var chkIdxArr = grd.getCheckedIndex("chk");
    if (chkIdxArr.length === 0) {
        scwin.showPopup("삭제할 행을 선택해주세요.");
        return;
    }
    userList.deleteRows(chkIdxArr);
};

scwin.btn_reset_onclick = function (e) {
    scwin.showPopup("모든 데이터를 초기화하시겠습니까?", true, function (result) {
        if (result) {
            userList.setData([]);
        }
    });
};

scwin.btn_search_onclick = function (e) {
    const tenantIdFromUrl = $p.getParameter("tenant");
    const searchKeywordValue = ipt_searchKeyword.getValue();

    if (!tenantIdFromUrl) {
        scwin.showPopup("테넌트 정보가 없습니다. 페이지를 새로고침 해주세요.");
        return;
    }

    var userDetailDataMap = $p.getComponentById("userDetail");
    if (userDetailDataMap) {
        userDetailDataMap.set("tenantId", tenantIdFromUrl);
        userDetailDataMap.set("searchKeyword", searchKeywordValue);
    } else {
        scwin.showPopup("userDetail DataMap을 찾을 수 없습니다.");
        return;
    }

    console.log("사용자 목록 조회 실행. 테넌트ID:", tenantIdFromUrl, "검색어:", searchKeywordValue);
    $p.executeSubmission("sbm_selectUserList");
};

scwin.btn_down_onclick = function (e) {
    var options = {
        fileName: "사용자관리.xlsx"
    };
    grd.advancedExcelDownload(options);
};

scwin.btn_save_onclick = function (e) {
    if (userList.getModifiedIndex().length === 0) {
        scwin.showPopup("저장할 변경사항이 없습니다.");
        return;
    }

    scwin.showPopup("변경 내용을 저장하시겠습니까?", true, function (result) {
        if (result) {
            scwin.validateAndSave();
        }
    });
};


scwin.processAndSaveUserData = function () {
    try {
        var modifiedIndices = userList.getModifiedIndex();
        var processedData = [];

        // 그리드 컴포넌트 참조 방법 수정
        var grid = null;
        try {
            grid = $p.getComponentById("grd") || window.mf_contentFrame_grd || grd;
        } catch (e) {
            console.log("그리드 참조 시도 중 오류:", e);
        }

        // 유효성 검사 (그리드 포커스 없이)
        for (let i = 0; i < modifiedIndices.length; i++) {
            const index = modifiedIndices[i];
            const rowData = userList.getRowJSON(index);
            const rowNum = index + 1;

            if (!rowData.name || rowData.name.trim() === "") {
                scwin.showPopup(`[${rowNum}행] 성명을 입력해주세요.`);
                return;
            }
            if (!rowData.email || rowData.email.trim() === "") {
                scwin.showPopup(`[${rowNum}행] 이메일을 입력해주세요.`);
                return;
            }
            if (!rowData.role || rowData.role.trim() === "") {
                scwin.showPopup(`[${rowNum}행] 역할을 선택해주세요.`);
                return;
            }

            // 새 행인 경우 비밀번호 필수 체크 (0000도 유효한 비밀번호로 인정)
            const rowStatus = userList.getRowStatus(index);
            if (rowStatus === "C" && (!rowData.password || rowData.password.trim() === "" || rowData.password === "******")) {
                scwin.showPopup(`[${rowNum}행] 새 사용자는 비밀번호를 입력해야 합니다.`);
                return;
            }
        }

        console.log("=== 클라이언트 전용 데이터 처리 시작 ===");

        // 테넌트 ID 유효성 검사 추가
        const tenantId = $p.getParameter("tenant");
        if (!tenantId || tenantId.trim() === "") {
            console.error("테넌트 ID가 유효하지 않습니다:", tenantId);
            scwin.showPopup("테넌트 정보가 없어 저장할 수 없습니다. 페이지를 새로고침해주세요.");
            return;
        }

        modifiedIndices.forEach(function (index) {
            var rowData = userList.getRowJSON(index);
            var rowStatus = userList.getRowStatus(index);

            // tenantId 강제 설정 및 검증
            if (!rowData.tenantId || rowData.tenantId.trim() === "") {
                rowData.tenantId = tenantId;
                console.log(`행 ${index}: tenantId 강제 설정 = ${tenantId}`);
            }

            // tenantId가 여전히 비어있으면 오류
            if (!rowData.tenantId || rowData.tenantId.trim() === "") {
                console.error(`행 ${index}: tenantId가 비어있음`, rowData);
                scwin.showPopup(`[${index + 1}행] 테넌트 정보가 없어 저장할 수 없습니다.`);
                return;
            }

            // 비밀번호 처리 로직 개선
            if (rowStatus === "U") {
                if (rowData.passwordChanged === "Y") {
                    if (!rowData.password || rowData.password === "" || rowData.password === "******") {
                        delete rowData.password;
                    }
                } else {
                    delete rowData.password;
                }
            } else if (rowStatus === "C") {
                // 새 행의 경우 비밀번호가 필수이므로 비어있으면 오류
                if (!rowData.password || rowData.password === "******") {
                    console.error("새 사용자의 비밀번호가 비어있습니다:", rowData);
                }
            }

            // 불필요한 필드 제거
            delete rowData.originalPassword;
            delete rowData.passwordChanged;
            delete rowData.chk; // 체크박스 필드 제거

            rowData.rowStatus = rowStatus;
            processedData.push(rowData);
        });

        var requestData = {
            saveDataList: processedData
        };

        console.log("서버로 전송할 데이터:", requestData);

        $.ajax({
            url: '/InsWebApp/saveUserList.pwkjson',
            type: 'POST',
            contentType: 'application/json',
            data: JSON.stringify(requestData),
            success: function (response) {
                console.log("저장 성공:", response);
                scwin.showPopup("저장이 완료되었습니다.", false, function () {
                    scwin.btn_search_onclick();
                });
            },
            error: function (xhr, status, error) {
                console.error("저장 실패:", {
                    status: xhr.status,
                    responseText: xhr.responseText,
                    error: error
                });

                var errorMessage = "저장 중 오류가 발생했습니다.";
                try {
                    var errorResponse = JSON.parse(xhr.responseText);
                    if (errorResponse.message) {
                        errorMessage += "\n" + errorResponse.message;
                    }
                } catch (e) {
                    errorMessage += "\n" + error;
                }

                scwin.showPopup(errorMessage);
            }
        });

    } catch (err) {
        console.error("데이터 처리 중 오류:", err);
        scwin.showPopup("데이터 처리 중 오류가 발생했습니다: " + err.message);
    }
};



scwin.validateAndSave = function () {
    console.log("=== 저장 시 이메일 중복 검사 시작 ===");
    const tenantId = $p.getParameter("tenant");
    const modifiedIndices = userList.getModifiedIndex();

    let emailsToCheck = [];
    let clientSideEmails = {};

    // 변경된 행에서 이메일 수집 및 클라이언트 자체 중복 검사
    for (let i = 0; i < modifiedIndices.length; i++) {
        const index = modifiedIndices[i];
        const email = userList.getCellData(index, "email").trim();
        const rowNum = index + 1;

        if (clientSideEmails[email]) {
            scwin.showPopup(`[${rowNum}행] 그리드 내에 동일한 이메일이 이미 존재합니다: ${email}`);
            return;
        }
        clientSideEmails[email] = true;
        emailsToCheck.push({ email: email, index: index, name: userList.getCellData(index, "name") });
    }

    if (emailsToCheck.length === 0) {
        scwin.processAndSaveUserData();
        return;
    }

    // 서버에 중복 검사 요청
    let checkedCount = 0;
    let duplicateResults = [];

    emailsToCheck.forEach(function (emailData) {
        $.ajax({
            url: '/InsWebApp/checkEmailByTenant.pwkjson',
            type: 'POST',
            contentType: 'application/json',
            data: JSON.stringify({ vo: { email: emailData.email, tenantId: tenantId } }),
            success: function (response) {
                let emailCheckResult = response.emailCheckResult || response.elData?.emailCheckResult;
                if (emailCheckResult === "unavailable") {
                    const userId = userList.getCellData(emailData.index, "userId");
                    if (!userId) { // 신규 행인데 DB에 이미 존재하면 중복
                        duplicateResults.push(emailData);
                    }
                }
            },
            error: function () {
                scwin.showPopup("이메일 중복 검사 중 오류가 발생했습니다.");
            },
            complete: function () {
                checkedCount++;
                if (checkedCount === emailsToCheck.length) {
                    if (duplicateResults.length > 0) {
                        let message = "다음 이메일이 이미 사용 중입니다. 수정 후 다시 저장해주세요.\n\n";
                        duplicateResults.forEach(item => {
                            message += `- ${item.email} (${item.name})\n`;
                        });
                        scwin.showPopup(message);
                    } else {
                        console.log("이메일 중복 없음. 실제 저장을 진행합니다.");
                        scwin.processAndSaveUserData();
                    }
                }
            }
        });
    });
};

scwin.sbm_saveUserList_onsubmit = function (e) {
    console.log("기존 submission 이벤트 - 무시됨");
    return false;
};

scwin.sbm_selectUserList_submitdone = function (e) {
    var responseData = e.responseJSON;
    if (!responseData || !responseData.userListVo || !Array.isArray(responseData.userListVo.userVoList)) {
        userList.removeAll();
        console.error("서버로부터 유효한 사용자 목록을 받지 못했습니다.");
        return;
    }

    var userArray = responseData.userListVo.userVoList;
    console.log("=== 원본 데이터 백업 시작 ===");

    userArray.forEach(function (user, index) {
        console.log(`사용자 ${index + 1} 원본 백업:`, {
            name: user.name,
            originalPasswordLength: user.password ? user.password.length : 0
        });

        user.originalPassword = user.password;
        user.password = "******";
        user.passwordChanged = "N";
    });

    userList.setJSON(userArray);
    console.log("사용자 목록 로딩 완료, 총", userArray.length, "개");

    setTimeout(function () {
        scwin.debugPasswordData();
    }, 1000);
};

scwin.sbm_saveUserList_onsubmit = function (e) {
    console.log("기존 submission 이벤트 - 무시됨");
    return false;
};
scwin.sbm_saveUserList_submitdone = function (e) {
    scwin.showPopup("저장이 완료되었습니다.", false, function () {
        scwin.btn_search_onclick();
    });
};

scwin.sbm_saveUserList_submitdone = function (e) {
    scwin.showPopup("저장이 완료되었습니다.", false, function () {
        scwin.btn_search_onclick();
    });
};

scwin.btn_upload_onclick = function (e) {
    console.log("=== Excel 업로드 시작 ===");
    console.log("현재 데이터 행 수:", userList.getTotalRow());

    // 원본 데이터 백업 (깊은 복사)
    scwin.originalDataCount = userList.getTotalRow();
    scwin.originalDataBackup = JSON.parse(JSON.stringify(userList.getAllJSON()));

    // 중복 실행 방지 플래그 추가
    scwin.uploadProcessing = false;

    console.log("백업 완료 - 원본 행 수:", scwin.originalDataCount);
    console.log("백업된 데이터:", scwin.originalDataBackup);

    try {
        var grid = $p.getComponentById("grd");
        if (!grid) {
            console.error("그리드를 찾을 수 없습니다.");
            return;
        }

        // **중요: type을 "1"로 변경하여 기존 데이터 유지하면서 새 데이터 추가**
        var options = {
            headerExist: "1",
            type: "1", // 기존 데이터 유지하면서 새 데이터 추가
            status: "C",
            mapping: [
                { "excelCol": "성명", "gridCol": "name" },
                { "excelCol": "이메일", "gridCol": "email" },
                { "excelCol": "비밀번호", "gridCol": "password" },
                { "excelCol": "역할", "gridCol": "role" }
            ]
        };

        console.log("업로드 옵션:", options);

        // 업로드 실행
        grid.advancedExcelUpload(options);

    } catch (err) {
        console.error("업로드 중 에러:", err);
        scwin.showPopup("업로드 중 오류가 발생했습니다: " + err.message);
    }
};


// START: 이 함수를 교체하거나 확인하세요
scwin.grd_onexcelupload = function (e) {
    console.log("=== Excel 업로드 후 데이터 병합 처리 시작 ===");

    try {
        // 1. 현재 userList에 있는 데이터는 엑셀에서 새로 업로드된 데이터입니다.
        const newData = userList.getAllJSON();
        if (!newData || newData.length === 0) {
            scwin.showPopup("업로드된 데이터가 없습니다.");
            if (scwin.originalDataBackup) {
                userList.setJSON(scwin.originalDataBackup); // 업로드 실패 시 원본 데이터로 복원
            }
            return;
        }
        console.log("새로 업로드된 데이터:", newData.length + "개");

        // 2. 이전에 백업해둔 원본 데이터를 가져옵니다.
        const originalData = scwin.originalDataBackup || [];
        console.log("백업된 기존 데이터:", originalData.length + "개");

        // 3. 기존 데이터와 새로운 데이터를 병합합니다.
        const combinedData = originalData.concat(newData);

        // 4. 병합된 데이터로 그리드를 다시 설정합니다.
        userList.setJSON(combinedData);

        const originalCount = originalData.length;
        const currentDataCount = combinedData.length;

        console.log(`병합 완료: 기존 ${originalCount}개, 신규 ${newData.length}개, 총 ${currentDataCount}개`);

        // 5. 새로 추가된 행들에 대해서만 후처리(테넌트 ID, 역할 매핑 등)를 실행합니다.
        for (var i = originalCount; i < currentDataCount; i++) {
            const tenantId = $p.getParameter("tenant");
            if (tenantId) {
                userList.setCellData(i, "tenantId", tenantId);
            }

            userList.setCellData(i, "passwordChanged", "Y");
            var currentPassword = userList.getCellData(i, "password");
            userList.setCellData(i, "originalPassword", currentPassword || "");
            if (!currentPassword || currentPassword.trim() === "") {
                userList.setCellData(i, "password", "");
            }
        }

        scwin.fixRoleMappingForNewData(originalCount);

        // 6. 업로드된 데이터에 대한 중복 검사를 시작합니다.
        setTimeout(function () {
            console.log("업로드된 데이터 중복 검사 시작...");
            scwin.checkUploadedEmailDuplicates(originalCount);
        }, 500);

    } catch (err) {
        console.error("업로드 후처리 중 에러:", err);
        scwin.showPopup("업로드 후 처리 중 오류가 발생했습니다: " + err.message);
        if (scwin.originalDataBackup) {
            userList.setJSON(scwin.originalDataBackup); // 오류 발생 시 원본 데이터로 복원
        }
    }
};
// END: 이 함수를 교체하거나 확인하세요


scwin.fixRoleMappingForNewData = function (startIndex) {
    var roleMapping = {
        "관리자": "admin",
        "매니저": "manager",
        "사용자": "user"
    };

    var totalRows = userList.getTotalRow();
    for (var i = startIndex; i < totalRows; i++) {
        var currentRole = userList.getCellData(i, "role");
        if (currentRole && roleMapping[currentRole]) {
            userList.setCellData(i, "role", roleMapping[currentRole]);
            console.log(`행 ${i} 역할 매핑: ${currentRole} -> ${roleMapping[currentRole]}`);
        }
    }
};

scwin.checkUploadedEmailDuplicates = function (startIndex) {
    console.log("=== 업로드된 데이터 이메일 중복 검사 시작 ===");

    try {
        var totalRows = userList.getTotalRow();
        var newUploadedEmails = [];

        // 새로 업로드된 데이터의 이메일만 수집
        for (var i = startIndex; i < totalRows; i++) {
            var email = userList.getCellData(i, "email");
            var name = userList.getCellData(i, "name") || "이름없음";

            if (email && email.trim() !== "") {
                newUploadedEmails.push({
                    email: email.trim(),
                    index: i,
                    name: name
                });
            }
        }

        console.log("새로 업로드된 이메일 수:", newUploadedEmails.length);

        if (newUploadedEmails.length === 0) {
            scwin.showPopup("업로드된 데이터에 이메일이 없습니다.\\n이메일을 입력한 후 다시 저장해주세요.");
            return;
        }

        // 클라이언트 내부 중복 검사 먼저 수행
        var clientDuplicates = scwin.findClientSideDuplicates(newUploadedEmails, startIndex);

        if (clientDuplicates.length > 0) {
            scwin.showClientDuplicateOptions(clientDuplicates, startIndex);
        } else {
            // 클라이언트 중복이 없으면 서버 중복 검사
            scwin.checkServerEmailDuplicates(newUploadedEmails, startIndex);
        }

    } catch (e) {
        console.error("중복 검사 중 에러 발생:", e);
        scwin.showPopup("중복 검사 중 오류가 발생했습니다: " + e.message);
    }
};

scwin.findClientSideDuplicates = function(newEmails, startIndex) {
    var allEmails = {};
    var duplicates = [];

    // 기존 데이터의 이메일 수집
    for (var i = 0; i < startIndex; i++) {
        var email = userList.getCellData(i, "email");
        if (email && email.trim()) {
            allEmails[email.trim()] = { index: i, isOriginal: true };
        }
    }

    // 새 데이터와 비교
    newEmails.forEach(function(emailData) {
        if (allEmails[emailData.email]) {
            duplicates.push({
                email: emailData.email,
                newIndex: emailData.index,
                existingIndex: allEmails[emailData.email].index,
                name: emailData.name
            });
        } else {
            allEmails[emailData.email] = { index: emailData.index, isOriginal: false };
        }
    });

    return duplicates;
};

scwin.showClientDuplicateOptions = function (duplicates, startIndex) {
    var message = "업로드된 데이터에 기존 데이터와 중복된 이메일이 있습니다:\\n\\n";

    duplicates.forEach(function (dup, index) {
        message += `${index + 1}. ${dup.email} (${dup.name})\\n`;
    });

    message += `\\n총 ${duplicates.length}개의 중복이 발견되었습니다.\\n\\n`;
    message += "확인: 화면에서 수정\\n취소: 중복 데이터 삭제";

    scwin.showPopup(message, true, function (result) {
        if (result) {
            scwin.showPopup("중복된 이메일을 수정한 후 저장해주세요.");
        } else {
            scwin.removeDuplicateRows(duplicates.map(d => d.newIndex));
        }
    });
};

scwin.removeDuplicateRows = function (indicesToRemove) {
    // 역순으로 정렬하여 인덱스 변경 문제 방지
    indicesToRemove.sort(function (a, b) { return b - a; });

    indicesToRemove.forEach(function (index) {
        userList.removeRow(index);
    });

    var currentDataCount = userList.getTotalRow();
    var remainingNewData = currentDataCount - scwin.originalDataCount;
    var removedCount = indicesToRemove.length;

    if (remainingNewData > 0) {
        scwin.showPopup(
            `중복 제거 완료!\\n` +
            `제거된 중복 데이터: ${removedCount}개\\n` +
            `추가된 새 데이터: ${remainingNewData}개\\n\\n` +
            `저장하시겠습니까?`,
            true,
            function (result) {
                if (result) {
                    scwin.btn_save_onclick();
                }
            }
        );
    } else {
        scwin.showPopup("모든 새 데이터가 중복으로 인해 제거되었습니다.\\n기존 데이터만 남아있습니다.");
    }
};


// 역할 매핑 처리
