// 업로드된 데이터의 서버 중복검사를 위한 수정된 함수
scwin.checkAllEmailDuplicates = function () {
    console.log("=== 이메일 중복 검사 시작 ===");

    try {
        var allData = userList.getAllJSON();
        var originalCount = scwin.originalDataCount || 0;

        console.log("전체 데이터 수:", allData.length);
        console.log("원본 데이터 수:", originalCount);

        if (allData.length <= originalCount) {
            console.log("새로운 데이터가 없어 중복 검사를 건너뜁니다.");
            scwin.showPopup("업로드된 새 데이터가 없습니다.");
            return;
        }

        var newUploadedEmails = [];

        // 새로 업로드된 데이터의 이메일만 수집 (강화된 로깅)
        for (var i = originalCount; i < allData.length; i++) {
            var email = userList.getCellData(i, "email");
            var name = userList.getCellData(i, "name") || "이름없음";

            console.log(`행 ${i} 검사:`, {
                name: name,
                email: email,
                emailLength: email ? email.length : 0
            });

            if (email && email.trim() !== "") {
                newUploadedEmails.push({
                    email: email.trim(),
                    index: i,
                    name: name
                });
                console.log(`이메일 추가됨: ${email} (${name})`);
            } else {
                console.log(`행 ${i}: 이메일이 비어있음`);
            }
        }

        console.log("수집된 이메일 수:", newUploadedEmails.length);
        console.log("수집된 이메일 목록:", newUploadedEmails.map(e => e.email));

        if (newUploadedEmails.length === 0) {
            console.log("검사할 이메일이 없습니다.");
            scwin.showPopup("업로드된 데이터에 이메일이 없습니다.\\n이메일을 입력한 후 다시 저장해주세요.");
            return;
        }

        // 서버와 중복검사 실행
        console.log("서버 중복검사 시작...");
        scwin.checkServerEmailDuplicates(newUploadedEmails);

    } catch (e) {
        console.error("중복 검사 중 에러 발생:", e);
        scwin.showPopup("중복 검사 중 오류가 발생했습니다: " + e.message);
    }
};

scwin.checkServerEmailDuplicates = function (emailList, startIndex) {
    const tenantId = $p.getParameter("tenant");
    if (!tenantId) {
        scwin.showPopup("테넌트 정보가 없어 중복검사를 진행할 수 없습니다.");
        return;
    }

    var duplicateResults = [];
    var checkedCount = 0;
    var totalCount = emailList.length;

    console.log("서버 중복검사 시작. 검사할 이메일:", totalCount);

    emailList.forEach(function (emailData) {
        $.ajax({
            url: '/InsWebApp/checkEmailByTenant.pwkjson',
            type: 'POST',
            contentType: 'application/json',
            data: JSON.stringify({
                vo: {
                    email: emailData.email,
                    tenantId: tenantId
                }
            }),
            success: function (response) {
                let emailCheckResult = response.emailCheckResult || response.elData?.emailCheckResult;

                if (emailCheckResult === "unavailable") {
                    duplicateResults.push(emailData);
                }
            },
            error: function (xhr, status, error) {
                console.error("이메일 중복검사 실패:", emailData.email, error);
            },
            complete: function() {
                checkedCount++;
                if (checkedCount === totalCount) {
                    scwin.processUploadDuplicateResults(duplicateResults, startIndex);
                }
            }
        });
    });
};

scwin.processUploadDuplicateResults = function (duplicateResults, startIndex) {
    console.log("업로드 중복검사 결과:", duplicateResults.length);

    if (duplicateResults.length > 0) {
        var message = "업로드된 데이터에 서버에 이미 존재하는 이메일이 발견되었습니다:\\n\\n";

        duplicateResults.forEach(function (duplicate, index) {
            message += `${index + 1}. ${duplicate.email} (${duplicate.name})\\n`;
        });

        message += `\\n총 ${duplicateResults.length}개의 중복이 있습니다.\\n\\n`;
        message += "확인: 화면에서 수정\\n취소: 중복 데이터 삭제";

        scwin.showPopup(message, true, function (result) {
            if (result) {
                scwin.showPopup("중복된 이메일을 수정한 후 저장해주세요.");
            } else {
                scwin.removeDuplicateRows(duplicateResults.map(d => d.index));
            }
        });
    } else {
        var addedCount = userList.getTotalRow() - startIndex;
        var message = `업로드 완료! 서버 중복 검사 통과\\n`;
        message += `추가된 새 데이터: ${addedCount}개\\n\\n저장하시겠습니까?`;

        scwin.showPopup(message, true, function (result) {
            if (result) {
                scwin.btn_save_onclick();
            }
        });
    }
};


// 중복검사 결과 처리 함수
scwin.processDuplicateResults = function (duplicateResults, totalCount) {
    console.log("=== 서버 중복검사 결과 처리 ===");
    console.log("전체 검사 수:", totalCount);
    console.log("중복된 이메일 수:", duplicateResults.length);
    console.log("중복 목록:", duplicateResults);

    if (duplicateResults.length > 0) {
        // 중복된 이메일 목록 표시
        var message = "업로드된 데이터에 중복된 이메일이 발견되었습니다:\\n\\n";

        duplicateResults.forEach(function (duplicate, index) {
            message += `${index + 1}. ${duplicate.email} (${duplicate.name})\\n`;
        });

        message += `\\n총 ${duplicateResults.length}개의 중복된 이메일이 있습니다.\\n\\n`;
        message += "어떻게 처리하시겠습니까?\\n\\n";
        message += "확인: 화면에서 직접 수정\\n";
        message += "취소: 중복 데이터 삭제";

        console.log("중복 처리 팝업 표시");
        scwin.showPopup(message, true, function (result) {
            if (result) {
                // 화면에서 직접 수정하도록 안내
                scwin.showPopup("중복된 데이터를 화면에서 직접 수정하신 후 저장 버튼을 눌러주세요.");
            } else {
                // 중복 데이터 삭제
                console.log("중복 데이터 삭제 진행");
                scwin.removeDuplicateUploadedData(duplicateResults);
            }
        });
    } else {
        // 중복이 없는 경우
        var addedCount = totalCount;
        var message = `업로드 완료! 이메일 중복이 없습니다.\\n`;
        message += `추가된 새 데이터: ${addedCount}개\\n\\n저장하시겠습니까?`;

        console.log("중복 없음 - 저장 확인 팝업 표시");
        scwin.showPopup(message, true, function (result) {
            if (result) {
                scwin.btn_save_onclick();
            }
        });
    }
};
// 중복된 업로드 데이터 제거 함수
scwin.removeDuplicateUploadedData = function (duplicateResults) {
    var indicesToRemove = duplicateResults.map(function (item) {
        return item.index;
    }).sort(function (a, b) { return b - a; }); // 역순 정렬

    // 중복 데이터 삭제
    indicesToRemove.forEach(function (index) {
        userList.removeRow(index);
    });

    var currentDataCount = userList.getTotalRow();
    var remainingNewData = currentDataCount - scwin.originalDataCount;
    var removedCount = indicesToRemove.length;

    if (remainingNewData > 0) {
        scwin.showPopup(
            "중복 제거 완료!\\n" +
            "제거된 중복 데이터: " + removedCount + "개\\n" +
            "추가된 새 데이터: " + remainingNewData + "개\\n\\n" +
            "저장하시겠습니까?",
            true,
            function (result) {
                if (result) {
                    scwin.btn_save_onclick();
                }
            }
        );
    } else {
        scwin.showPopup("모든 새 데이터가 중복으로 인해 제거되었습니다.\\n기존 데이터만 남아있습니다.");
    }
};

// 중복 이메일 옵션 표시
scwin.showDuplicateEmailOptions = function (duplicateEmails) {
    var message = "업로드된 데이터에 중복된 이메일이 있습니다:\\n\\n";
    var totalDuplicates = 0;

    duplicateEmails.forEach(function (group) {
        message += "[ " + group.email + " ]\\n";
        var newRows = group.rows.filter(function (row) { return !row.isOriginal; });
        if (newRows.length > 0) {
            totalDuplicates += newRows.length;
        }
    });

    message += "\\n총 " + totalDuplicates + "개의 중복된 새 데이터가 있습니다.\\n\\n";
    message += "어떻게 처리하시겠습니까?\\n\\n확인: 화면에서 직접 수정\\n취소: 중복 데이터 삭제";

    scwin.showPopup(message, true, function (result) {
        if (result) {
            scwin.showPopup("중복된 데이터를 화면에서 직접 수정하신 후 저장 버튼을 눌러주세요.");
        } else {
            scwin.removeDuplicateNewData(duplicateEmails);
        }
    });
};

// 중복 데이터 제거
scwin.removeDuplicateNewData = function (duplicateEmails) {
    var indicesToRemove = [];

    duplicateEmails.forEach(function (group) {
        group.rows.forEach(function (row) {
            if (!row.isOriginal) {
                indicesToRemove.push(row.index);
            }
        });
    });

    indicesToRemove = [...new Set(indicesToRemove)].sort(function (a, b) { return b - a; });

    indicesToRemove.forEach(function (index) {
        userList.removeRow(index);
    });

    var currentDataCount = userList.getTotalRow();
    var remainingNewData = currentDataCount - scwin.originalDataCount;
    var removedCount = indicesToRemove.length;

    if (remainingNewData > 0) {
        scwin.showPopup("중복 제거 완료!\\n제거된 중복 데이터: " + removedCount + "개\\n추가된 새 데이터: " + remainingNewData + "개\\n\\n저장하시겠습니까?", true, function (result) {
            if (result) {
                scwin.btn_save_onclick();
            }
        });
    } else {
        scwin.showPopup("모든 새 데이터가 중복으로 인해 제거되었습니다.\\n기존 데이터만 남아있습니다.");
    }
};

scwin.grd_oncellindexchange = function (newRowIndex, newColIndex, oldRowIndex, oldColIndex) {
    try {
        const grid = $p.getComponentById("grd");
        if (!grid) {
            console.log("그리드 컴포넌트를 찾을 수 없습니다.");
            return;
        }

        const oldColId = grid.getColumnID(oldColIndex);

        if (oldColId === "password") {
            const passwordValue = userList.getCellData(oldRowIndex, "password");

            if (passwordValue && passwordValue !== "" && passwordValue !== "******") {
                userList.setCellData(oldRowIndex, "passwordChanged", "Y");
                console.log(`행 ${oldRowIndex}: 비밀번호 입력됨, 변경 플래그 설정`);
            }
        }

        if (oldColId === "email") {
            const emailValue = userList.getCellData(oldRowIndex, "email");

            if (!emailValue || emailValue.trim() === "") {
                return;
            }

            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(emailValue)) {
                scwin.showPopup("올바른 이메일 형식이 아닙니다.", false, function () {
                    setTimeout(function () {
                        try {
                            grid.focusCell(oldRowIndex, oldColIndex);
                        } catch (e) {
                            console.log("셀 포커스 설정 실패:", e);
                        }
                    }, 100);
                });
                return;
            }

            scwin.checkEmailDuplicate(emailValue, oldRowIndex);
        }
    } catch (e) {
        console.error("셀 인덱스 변경 처리 중 오류:", e);
    }
};

scwin.grd_oncellclick = function (row, col) {
    var grid = $p.getComponentById("grd");
    var colId = grid.getColumnID(col);

    if (colId === "password") {
        var currentValue = userList.getCellData(row, "password");
        if (currentValue === "******") {
            userList.setCellData(row, "password", "");
            userList.setCellData(row, "passwordChanged", "Y");
            console.log("비밀번호 변경 모드로 전환 - 행:", row);
        }
    }
};

// 이메일 중복 확인
scwin.checkEmailDuplicate = function (email, rowIndex) {
    const tenantId = $p.getParameter("tenant");

    if (!tenantId) {
        console.error("테넌트 ID를 찾을 수 없어 이메일 중복 검사를 중단합니다.");
        return;
    }

    $.ajax({
        url: '/InsWebApp/checkEmailByTenant.pwkjson',
        type: 'POST',
        contentType: 'application/json',
        data: JSON.stringify({
            vo: {
                email: email,
                tenantId: tenantId
            }
        }),
        success: function (response) {
            let emailCheckResult = response.emailCheckResult || response.elData?.emailCheckResult;

            if (emailCheckResult === "unavailable") {
                scwin.showPopup("'" + email + "'은(는) 이미 사용 중인 이메일입니다.\\n다른 이메일을 입력해주세요.", false, function () {
                    try {
                        const grid = $p.getComponentById("grd");
                        if (grid && userList.getRowStatus(rowIndex) === "C") {
                            userList.setCellData(rowIndex, "email", "");
                            setTimeout(function () {
                                try {
                                    grid.focusCell(rowIndex, grid.getColumnIndex("email"));
                                } catch (e) {
                                    console.log("셀 포커스 설정 실패:", e);
                                }
                            }, 100);
                        }
                    } catch (e) {
                        console.log("이메일 중복 처리 중 오류:", e);
                    }
                });
            }
        },
        error: function (xhr, status, error) {
            console.error("이메일 중복검사 오류:", error);
            scwin.showPopup("이메일 중복검사 중 오류가 발생했습니다.");
        }
    });
};

scwin.grd_oncellclick = function (row, col) {
    var grid = $p.getComponentById("grd");
    var colId = grid.getColumnID(col);

    if (colId === "password") {
