        if (currentValue === "******") {
            userList.setCellData(row, "password", "");
            userList.setCellData(row, "passwordChanged", "Y");
            console.log("비밀번호 변경 모드로 전환 - 행:", row);
        }
    }
};

scwin.debugPasswordData = function () {
    console.log("=== 현재 비밀번호 데이터 상태 ===");

    var totalRows = userList.getTotalRow();
    for (var i = 0; i < totalRows; i++) {
        var rowData = userList.getRowJSON(i);
        console.log(`행 ${i}:`, {
            name: rowData.name,
            password: rowData.password,
            originalPassword: rowData.originalPassword,
            passwordChanged: rowData.passwordChanged,
            rowStatus: userList.getRowStatus(i)
        });
    }
};
